void kernel_relu_s8_dronet(const int8_t *input, int8_t *output, int n) {
    size_t vl;
    int i = 0;
    
    /* Main loop with LMUL=8 for maximum throughput */
    size_t vlmax = __riscv_vsetvlmax_e8m8();
    for (; i + vlmax <= n; i += vlmax) {
        vint8m8_t v = __riscv_vle8_v_i8m8(input + i, vlmax);
        v = __riscv_vmax_vx_i8m8(v, 0, vlmax);
        __riscv_vse8_v_i8m8(output + i, v, vlmax);
    }
    
    /* Tail loop for remaining elements */
    if (i < n) {
        vl = __riscv_vsetvl_e8m8(n - i);
        vint8m8_t v = __riscv_vle8_v_i8m8(input + i, vl);
        v = __riscv_vmax_vx_i8m8(v, 0, vl);
        __riscv_vse8_v_i8m8(output + i, v, vl);
    }
}

void kernel_sigmoid_s8_dronet(const int8_t *input, int8_t *output, int n,
                       float scale_in, float scale_out,
                       int activation_min, int activation_max) {
    const float inv_scale_out = 1.0f / scale_out;
    const int8_t min_clamp = (int8_t)activation_min;
    const int8_t max_clamp = (int8_t)activation_max;
    
    for (int i = 0; i < n; i++) {
        float fv = (float)input[i] * scale_in;
        float sig = 1.0f / (1.0f + expf(-fv));
        float scaled = sig * inv_scale_out;
        int32_t v = (int32_t)(scaled + 0.5f);
        if (v < activation_min) v = activation_min;
        if (v > activation_max) v = activation_max;
        output[i] = (int8_t)v;
    }
}
